-- 03_seed_data.sql
-- PostgreSQL / database: volkswagen
-- Seed data adapted to the provided schema.
-- 10,000 cars + 10,000 profiles + 10 dealers + car/dealer links.
-- ============================================================
BEGIN;

-- Cars: GENERATED ALWAYS AS IDENTITY -> explicit IDs require OVERRIDING SYSTEM VALUE.

-- Profiles: bodywork is normalized to the lowercase enum values; electric engine volume 0 becomes NULL.

-- Dealers: normalized to the schema column dealer_showroom_address and E.164 phone format.

-- Cars <-> Dealers




















-- Synchronize identity sequences after explicit IDs.
SELECT setval(pg_get_serial_sequence('cars', 'id'), (SELECT MAX(id) FROM cars));
SELECT setval(pg_get_serial_sequence('dealers', 'dealer_id'), (SELECT MAX(dealer_id) FROM dealers));

COMMIT;